import pandas as pdimport mathimport redef compare_monthly_expenses(df, month1, month2):    columns = [        "Category",        month1 if isinstance(month1, str) else "Month 1",        month2 if isinstance(month2, str) else "Month 2",        "Difference",        "Change"    ]    if not isinstance(df, pd.DataFrame):        return pd.DataFrame(columns=columns)    required_columns = ["Date", "Type", "Category", "Amount"]    if not all(column in df.columns for column in required_columns):        return pd.DataFrame(columns=columns)    if not isinstance(month1, str) or not isinstance(month2, str):        return pd.DataFrame(columns=columns)    month_pattern = r"^\d{4}-(0[1-9]|1[0-2])$"    if not re.match(month_pattern, month1):        return pd.DataFrame(columns=columns)    if not re.match(month_pattern, month2):        return pd.DataFrame(columns=columns)    if month1 == month2:        return pd.DataFrame(columns=columns)    expense_df = df[df["Type"] == "Expense"].copy()    if expense_df.empty:        return pd.DataFrame(columns=columns)    try:        expense_df["Date"] = pd.to_datetime(            expense_df["Date"], errors="raise"        )        expense_df["Amount"] = pd.to_numeric(            expense_df["Amount"], errors="raise"        )    except (TypeError, ValueError):        return pd.DataFrame(columns=columns)    if expense_df["Date"].isna().any():        return pd.DataFrame(columns=columns)    if not all(        math.isfinite(value) and value >= 0        for value in expense_df["Amount"]    ):        return pd.DataFrame(columns=columns)    if expense_df["Category"].isna().any():        return pd.DataFrame(columns=columns)    if not expense_df["Category"].apply(        lambda value: isinstance(value, str) and bool(value.strip())    ).all():        return pd.DataFrame(columns=columns)    expense_df["Month"] = (        expense_df["Date"].dt.to_period("M").astype(str)    )    comparison = expense_df[        expense_df["Month"].isin([month1, month2])    ].groupby(        ["Category", "Month"]    )["Amount"].sum().unstack(fill_value=0)    for month in [month1, month2]:        if month not in comparison.columns:            comparison[month] = 0    comparison["Difference"] = (        comparison[month2] - comparison[month1]    )    comparison["Change"] = comparison["Difference"].apply(        lambda x: "Increased" if x > 0        else "Decreased" if x < 0        else "No Change"    )    return comparison.reset_index()[columns]